<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Luxora Admin</title><style>body{font:15px system-ui;margin:2rem;max-width:1000px}table{border-collapse:collapse;width:100%;margin:1rem 0}td,th{border:1px solid #ddd;padding:.5rem;text-align:left}.metric{display:inline-block;padding:1rem;background:#f4f4f4;margin-right:.5rem}</style></head><body><h1>Luxora commerce dashboard</h1>@if(session('success'))<p>{{ session('success') }}</p>@endif<div><span class="metric">Products {{ $metrics['products'] }}</span><span class="metric">Orders {{ $metrics['orders'] }}</span><span class="metric">Pending payment {{ $metrics['pending'] }}</span></div><h2>Inventory</h2><table><tr><th>Product</th><th>SKU</th><th>Stock</th><th>Save</th></tr>@foreach($products as $product)@foreach($product->variants as $variant)<tr><td>{{ $product->name }}</td><td>{{ $variant->sku }}</td><td><form method="post" action="{{ route('admin.luxora.stock.update', $variant) }}">@csrf @method('PATCH')<input type="number" name="stock" min="0" value="{{ $variant->stock }}"><button>Save</button></form></td><td>{{ $variant->updated_at }}</td></tr>@endforeach @endforeach</table><h2>Orders</h2><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Payment</th><th>Action</th></tr>@foreach($orders as $order)<tr><td>{{ $order->id }}</td><td>{{ $order->customer_name }}<br>{{ $order->email }}</td><td>${{ number_format($order->total_cents / 100, 2) }}</td><td>{{ $order->payment_status }}</td><td>@if($order->payment_status !== 'paid')<form method="post" action="{{ route('admin.luxora.orders.mark-paid', $order) }}">@csrf<button>Record manual payment</button></form>@endif</td></tr>@endforeach</table></body></html>
